const call = async (fn: any, url: string, as: string | null, init: any = {}, extra: any = {}) => {
  const headers: any = { 'content-type': 'application/json', 'x-forwarded-for': extra.ip || '10.0.0.1' }; if (as) headers.authorization = 'Bearer ' + as;
  const r = await fn(new Request('http://x' + url, { ...init, headers }), extra.ctx);
  return { status: r.status, json: await r.json().catch(() => null), headers: r.headers };
};
