      it = plan([mk('r1', 'A', 'x1', { technique: tj(blk(2, 7, '21')) })])[0]; assert.deepEqual(it.setPlan[0].loads, ['INF', 'SUP', 'FULL']); assert.deepEqual(plan([mk('r1', 'A', 'x1', { technique: tj(blk(1, 7, 'Método 21')) })])[0].setPlan[0].loads, ['INF', 'SUP', 'FULL'], 'apelido da técnica vale igual');
