      assert.equal(dayFocus(['PEITO', 'triceps', 'TRÍCEPS', 'Ombro']), 'Peito, Tríceps e Ombros', 'sem acento nem maiúscula; os mais frequentes, na ordem em que aparecem'); assert.equal(dayFocus(['Peito', 'Costas', 'Pernas', 'Peito']), 'Peito, Costas e Pernas');
      assert.equal(dayFocus(['Peito', 'Costas', 'Pernas', 'Ombros']), 'Corpo inteiro', '4 grupos ou mais'); assert.equal(dayFocus(['Peito', 'Costas', 'Pernas', 'Ombros', 'Peito', 'Peito']), 'Corpo inteiro');
      assert.equal(dayFocus(['Mobilidade', 'Cardio']), null, 'só mobilidade/cardio: sem nome'); assert.equal(dayFocus(['Mobilidade', 'Peito', 'Cardio']), 'Peito', 'mobilidade e cardio não contam'); assert.equal(dayFocus([]), null); assert.equal(dayFocus([null, undefined, '', '  ']), null);
