      assert.deepEqual(parseProgressBody({ vid: V1 }), { ok: true, vid: V1, value: { loads: {}, prev: {}, done: {}, swaps: {} } }, 'só o vid é obrigatório');
      const NOW = Date.UTC(2026, 9, 5, 15, 0, 0);
