      assert.deepEqual(full.value, { loads: { [K1]: { '0_0': '60', '1_0': '62.5', '3_1': '50', '12_4': '1' } }, prev: { [K1]: { '0_0': '57.5' } }, done: { [K1]: NOW - 1000 }, swaps: { [K1]: K2 } }, 'o que é válido passa e o resto do corpo é ignorado');
      const dirty: any = parseProgressBody({ vid: V1, loads: { 'curta': { '0_0': '1' }, [K1]: { 'x_y': '1', '100_0': '1', '0_10': '1', '0_0': 'abc', '1_0': '1e5', '2_0': '12345', '3_0': '1.234', '4_0': '-5', '5_0': 5, '6_0': '', '7_0': ' 60', '8_0': '<b>', '9_0': '60 ', '10_0': '0', '11_0': '9999.99' }, [K2]: 'texto', [K3]: [1, 2] }, prev: 'x', done: { [K1]: 'agora', [K2]: 1, [K3]: NOW + 10 * 86400000, 'curta': NOW }, swaps: { [K1]: 'zzz', [K2]: 5, [K3]: K1, 'curta': K1 } }, NOW);
      assert.deepEqual(dirty.value, { loads: { [K1]: { '10_0': '0', '11_0': '9999.99' } }, prev: {}, done: {}, swaps: { [K3]: K1 } }, 'valores, campos, chaves, horários e trocas tortos são descartados');
      { const pollute: any = parseProgressBody(JSON.parse('{"vid":"' + V1 + '","loads":{"__proto__":{"0_0":"1"},"constructor":{"0_0":"1"}},"done":{"__proto__":1}}'), NOW); assert.deepEqual(pollute.value.loads, {}); assert.equal(({} as any)['0_0'], undefined, 'sem poluir o protótipo'); }
      // tetos: exercícios e valores
      { const many: any = {}; for (let i = 0; i < 90; i++) many[('0000000000' + i.toString(16)).slice(-12).padStart(12, '0')] = { '0_0': '1' }; const r: any = parseProgressBody({ vid: V1, loads: many, done: Object.fromEntries(Object.keys(many).map((k) => [k, NOW])), swaps: Object.fromEntries(Object.keys(many).map((k) => [k, K1])) }, NOW); assert.equal(Object.keys(r.value.loads).length, MAX_PROGRESS_EXERCISES); assert.equal(Object.keys(r.value.done).length, MAX_PROGRESS_EXERCISES); assert.equal(Object.keys(r.value.swaps).length, MAX_PROGRESS_EXERCISES); assert.equal(MAX_PROGRESS_EXERCISES, 60);
        const big: any = {}; for (let e = 0; e < 40; e++) { const k = ('0000000000' + e.toString(16)).slice(-12).padStart(12, '0'); big[k] = {}; for (let sI = 0; sI < 30; sI++) for (let f = 0; f < 3; f++) big[k][sI + '_' + f] = '10'; }
        const r2: any = parseProgressBody({ vid: V1, loads: big, prev: big }, NOW); const total = Object.values(r2.value.loads).concat(Object.values(r2.value.prev)).reduce((n: number, o: any) => n + Object.keys(o).length, 0); assert.equal(total, MAX_PROGRESS_ENTRIES, 'no máximo 1500 valores por envio (atuais + anteriores)'); assert.equal(MAX_PROGRESS_ENTRIES, 1500); }
      // guardar por aparelho: substitui o mesmo, até 3 mais recentes, tolera coluna torta
