        m = mergeProgress(m.json, V4, snap('3'), new Date('2026-10-05T14:00:00Z')); assert.equal(m.devices, MAX_PROGRESS_DEVICES); assert.equal(MAX_PROGRESS_DEVICES, 3); assert.deepEqual(Object.keys(JSON.parse(m.json)).sort(), [V2, V3, V4].sort(), 'sai o aparelho mais antigo (V1)');
        m = mergeProgress(m.json, V2, snap('9'), new Date('2026-10-05T15:00:00Z')); m = mergeProgress(m.json, V1, snap('8'), new Date('2026-10-05T16:00:00Z')); assert.deepEqual(Object.keys(JSON.parse(m.json)).sort(), [V1, V2, V4].sort(), 'depois de V2 e V1 voltarem, sai o mais antigo (V3)');
