      assert.equal(R.workout, 'Teste da Lead'); assert.deepEqual([R.access.trial, R.access.name, R.access.code], [true, 'Lead do Insta', trialLk.code]); assert.ok(R.access.viewCount >= 1 && R.access.doneCount === 1 && typeof R.access.lastViewedAt === 'string' && typeof R.access.lastDoneAt === 'string' && R.access.status === 'ACTIVE');
      assert.deepEqual(R.progress.devices, 1); assert.equal(typeof R.progress.updatedAt, 'string'); assert.deepEqual(R.dones.map((d: any) => d.day), ['A']); assert.deepEqual(R.days.map((d: any) => d.label), ['TREINO 1 - Peito e Costas', 'TREINO 2 - Pernas']);
      const dA = R.days[0]; assert.ok(typeof dA.doneAt === 'string', 'dia A concluído'); assert.equal(R.days[1].doneAt, null); assert.deepEqual([R.totals.daysDone, R.totals.daysTotal], [1, 2]);
      const eS = dA.exercises.find((e: any) => e.key === supino.key); assert.equal(eS.done, true); assert.equal(typeof eS.doneAt, 'string'); assert.equal(eS.setsLogged, 4); assert.deepEqual(eS.sets[3], { n: 4, reps: '8 reps', tech: 'DROP-SET', labels: ['CARGA', 'CARGA DO DROP'], cur: ['65', '50'], prev: ['62.5', '47.5'] }); assert.deepEqual(eS.sets[0].cur, ['60']); assert.deepEqual([eS.topCur, eS.topPrev, eS.delta], [65, 62.5, 2.5]); assert.equal(eS.volumeCur, 2370); assert.equal(eS.volumePrev, 2275);
      assert.equal(dA.volumeCur, 2370); assert.equal(dA.volumePrev, 2275); assert.equal(dA.setsLogged, 4); assert.equal(R.totals.setsLogged, 4); assert.deepEqual([dA.exercisesDone, R.totals.exercisesDone], [1, 1]); assert.ok(dA.exercisesTotal >= 4 && R.totals.exercisesTotal > dA.exercisesTotal);
      const eMob = dA.exercises.find((e: any) => e.section === 'MOBILIDADE'); assert.deepEqual(eMob.sets, [], 'mobilidade não tem carga'); assert.equal(eMob.setsLogged, 0); assert.deepEqual([eMob.topCur, eMob.delta], [null, null]);
      assert.ok(!json.includes(V1) && !json.includes(V2), 'o relatório não entrega o id do aparelho'); assert.ok(!/ana@secreto|5511999990000|NOTA INTERNA|createdById|"progress":"/.test(json), 'nada interno'); assert.ok(!/<|javascript:/i.test(json));
      // troca de exercício aparece com o nome da troca; carga de técnica personalizada com 3 caixas
      { const sw = (agach.swaps || [])[0]; const agSnap = { vid: V1, loads: { [agach.key]: { '0_0': '80', '0_1': '70', '0_2': '60' } }, swaps: sw ? { [agach.key]: sw.key } : {} }; await send(trialLk.code, agSnap, '10.20.7.4'); const R2 = (await rep(trialLk.code)).json.report; const eA = R2.days[1].exercises.find((e: any) => e.key === agach.key); assert.deepEqual(eA.sets[0].labels, ['CARGA', 'PASSO 2', 'PASSO 3']); assert.deepEqual(eA.sets[0].cur, ['80', '70', '60']); assert.deepEqual([eA.topCur, eA.topPrev, eA.delta], [80, null, null]); assert.equal(eA.volumeCur, 8 * 80, 'só a 1ª caixa entra no volume'); if (sw) { assert.equal(eA.name, sw.name); assert.equal(eA.swapped, true); } assert.equal(R2.days[0].exercises.find((e: any) => e.key === supino.key).setsLogged, 0, 'o último envio vale (o aparelho substitui o anterior)'); }
