      { const sw = (supino.swaps || [])[0]; assert.ok(sw && sw.key && sw.name, 'o supino do plano tem troca'); await send(trialLk.code, { vid: V1, loads: { [supino.key]: { '0_0': '60' } }, swaps: { [supino.key]: sw.key } }, '10.20.7.9'); const Rs = (await rep(trialLk.code)).json.report; const es = Rs.days[0].exercises.find((e: any) => e.key === supino.key); assert.equal(es.name, sw.name); assert.equal(es.swapped, true);
        await send(trialLk.code, { vid: V1, loads: { [supino.key]: { '0_0': '60' } }, swaps: { [supino.key]: 'bbbbbbbbbbbb' } }, '10.20.7.9'); const Rt = (await rep(trialLk.code)).json.report; const et = Rt.days[0].exercises.find((e: any) => e.key === supino.key); assert.equal(et.name, supino.name, 'troca que não existe mais no treino: volta ao nome do plano'); assert.equal(et.swapped, false);
        await send(trialLk.code, { vid: V1, loads: { [supino.key]: { '0_0': '60' } }, swaps: {} }, '10.20.7.9'); }
      // dados do dia: só as conclusões deste link, da mais antiga para a mais nova, até 200
      { const other = await mkT({ trial: true, notifyDone: true }); await call(donePOST, '/api/treino-publico/' + other.code + '/concluido', null, { method: 'POST', body: JSON.stringify({ vid: V3, day: 'A' }) }, { ctx: { params: { code: other.code } }, ip: '10.20.8.1' });
        const mine = row(); const before = (await rep(trialLk.code)).json.report; assert.equal(before.dones.length, 1, 'a conclusão do OUTRO link não aparece aqui'); assert.equal(before.access.doneCount, 1);
        S.dones.push({ id: 'dnx1', shareId: mine.id, vid: V2, day: 'B', createdAt: new Date('2026-01-01T00:00:00Z') }); const ord = (await rep(trialLk.code)).json.report; assert.deepEqual(ord.dones.map((d: any) => d.day), ['B', 'A'], 'da mais antiga para a mais nova'); assert.equal(ord.days[1].doneAt, '2026-01-01T00:00:00.000Z');
        for (let i = 0; i < 250; i++) S.dones.push({ id: 'dnc' + i, shareId: mine.id, vid: 'e' + String(i).padStart(15, '0'), day: 'Z' + i, createdAt: new Date(Date.UTC(2026, 5, 1) + i * 1000) }); const cap = (await rep(trialLk.code)).json.report; assert.equal(cap.dones.length, 200, 'no máximo 200 conclusões'); assert.equal(cap.dones[0].day, 'B'); S.dones = S.dones.filter((d: any) => !/^dn(x|c)/.test(d.id)); S.dones = S.dones.filter((d: any) => d.shareId !== other.id && true); }
      // limite de consultas do coach: 120 por hora, por pessoa
      { for (let i = 0; i < 120; i++) { const x = await rep(trialLk.code, adm('cRL')); assert.equal(x.status, 403, 'consulta ' + i); } const lim = await rep(trialLk.code, adm('cRL')); assert.equal(lim.status, 429, '121ª consulta'); assert.ok(/Muitas consultas/.test(lim.json.error)); assert.equal((await rep(trialLk.code, adm(PAULO_ID))).status, 200, 'o limite é por pessoa'); }
