      { const qM = (await post({ name: 'Some', data: JSON.stringify(QD()) })).json.quick.id; const lkM = (await call(sharePOST, '/api/workout-share', adm(PAULO_ID), { method: 'POST', body: JSON.stringify({ quickWorkoutId: qM, expiresInHours: 168, trial: true }) })).json.share; assert.equal((await rep(lkM.code)).status, 200); S.quicks = S.quicks.filter((q: any) => q.id !== qM); const gone = await rep(lkM.code); assert.equal(gone.status, 404); assert.ok(/não existe mais/.test(gone.json.error)); }
